import { Zap, Shield, Globe, BarChart2, Users, RefreshCw } from 'lucide-react';

const features = [
  { icon: Zap,       title: 'Lightning fast',     desc: 'Sub-second response times with edge caching and optimized pipelines.' },
  { icon: Shield,    title: 'Enterprise security', desc: 'SOC 2 Type II certified with end-to-end encryption and SSO support.' },
  { icon: Globe,     title: 'Global CDN',          desc: 'Your data, delivered from 200+ edge locations worldwide.' },
  { icon: BarChart2, title: 'Advanced analytics',  desc: 'Real-time dashboards and custom reports for every metric that matters.' },
  { icon: Users,     title: 'Team collaboration',  desc: 'Built-in comments, mentions, and role-based access control.' },
  { icon: RefreshCw, title: 'Continuous sync',     desc: 'Webhooks, live updates, and conflict-free real-time merges.' },
];

export function Features() {
  return (
    <section className="py-24 px-6 max-w-6xl mx-auto">
      <div className="text-center mb-14">
        <h2 className="text-3xl font-bold text-slate-800 mb-3">Everything you need</h2>
        <p className="text-slate-500 max-w-md mx-auto">From solo side projects to enterprise scale — Acme grows with you.</p>
      </div>
      <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-6">
        {features.map((f) => (
          <div key={f.title} className="p-6 rounded-2xl border border-slate-100 bg-white shadow-sm hover:shadow-md hover:-translate-y-0.5 transition-all">
            <div className="w-10 h-10 rounded-xl bg-violet-50 flex items-center justify-center mb-4">
              <f.icon className="h-5 w-5 text-violet-600" />
            </div>
            <h3 className="font-semibold text-slate-800 mb-1">{f.title}</h3>
            <p className="text-sm text-slate-500 leading-relaxed">{f.desc}</p>
          </div>
        ))}
      </div>
    </section>
  );
}

/components/Pricing.tsx.content:
import { Check } from 'lucide-react';

const plans = [
  { name: 'Starter', price: 'Free', features: ['5 projects', '1 GB storage', 'Community support', 'Basic analytics'], cta: 'Get started', highlighted: false },
  { name: 'Pro',     price: '$29/mo', features: ['Unlimited projects', '50 GB storage', 'Priority support', 'Advanced analytics', 'Custom domains'], cta: 'Start free trial', highlighted: true, badge: 'Most popular' },
  { name: 'Team',    price: '$79/mo', features: ['Everything in Pro', 'Team workspaces', 'SSO & SAML', 'Audit logs', 'SLA guarantee'], cta: 'Contact sales', highlighted: false },
];

export function Pricing() {
  return (
    <section className="py-24 px-6 bg-slate-50">
      <div className="text-center mb-14 max-w-6xl mx-auto">
        <h2 className="text-3xl font-bold text-slate-800 mb-3">Simple, transparent pricing</h2>
        <p className="text-slate-500">No hidden fees. Cancel anytime.</p>
      </div>
      <div className="grid grid-cols-1 md:grid-cols-3 gap-6 max-w-5xl mx-auto">
        {plans.map((p) => (
          <div key={p.name} className={`rounded-2xl p-7 flex flex-col ${p.highlighted ? 'bg-violet-600 text-white shadow-2xl shadow-violet-500/30 ring-2 ring-violet-400 scale-105' : 'bg-white border border-slate-200 shadow-sm'}`}>
            {p.badge && (
              <span className="self-start text-xs font-bold bg-white/20 text-white px-2.5 py-1 rounded-full mb-4">{p.badge}</span>
            )}
            <h3 className={`text-lg font-bold mb-1 ${p.highlighted ? 'text-white' : 'text-slate-800'}`}>{p.name}</h3>
            <p className={`text-4xl font-extrabold mb-6 ${p.highlighted ? 'text-white' : 'text-slate-800'}`}>{p.price}</p>
            <ul className="space-y-2.5 flex-1 mb-8">
              {p.features.map((f) => (
                <li key={f} className="flex items-center gap-2 text-sm">
                  <Check className={`h-4 w-4 flex-shrink-0 ${p.highlighted ? 'text-violet-200' : 'text-violet-500'}`} />
                  <span className={p.highlighted ? 'text-violet-100' : 'text-slate-600'}>{f}</span>
                </li>
              ))}
            </ul>
            <button className={`w-full py-2.5 rounded-xl font-semibold text-sm transition-colors ${p.highlighted ? 'bg-white text-violet-700 hover:bg-violet-50' : 'bg-violet-600 text-white hover:bg-violet-700'}`}>
              {p.cta}
            </button>
          </div>
        ))}
      </div>
    </section>
  );
}

